mapper.select:
WITH bom_tree AS ( SELECT 0 AS bom_level, CAST(NULL AS VARCHAR(20)) AS parent_item_code, i.item_code, CAST(1 AS DECIMAL(18, 4)) AS qty_per_parent, CAST(1 AS DECIMAL(18, 4)) AS total_qty, CAST(NULL AS VARCHAR(10)) AS process_code, CAST(i.item_code AS VARCHAR(400)) AS sort_path FROM item i WHERE i.item_code = #{itemCode}
UNION ALL
SELECT t.bom_level + 1, b.parent_item_code, b.child_item_code, CAST(b.qty AS DECIMAL(18, 4)), CAST(t.total_qty * b.qty AS DECIMAL(18, 4)), b.process_code, CAST(t.sort_path + '>' + b.child_item_code AS VARCHAR(400)) FROM bom_tree t JOIN bom b ON b.parent_item_code = t.item_code ) SELECT t.bom_level, t.parent_item_code, t.item_code, i.item_name, i.item_type, i.unit, t.qty_per_parent, t.total_qty, t.process_code FROM bom_tree t JOIN item i ON i.item_code = t.item_code ORDER BY t.sort_path OPTION (MAXRECURSION 20)
